import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `${field({ id: "nfSiteName", label: "Site name", value: "My Website" })}${field({ id: "nfSiteUrl", label: "Site URL", value: "https://example.com" })}${textarea({ id: "nfMessage", label: "Custom message", value: "The page you are looking for does not exist or has been moved." })}${checkbox({ id: "nfNav", label: "Include navigation links", checked: true })}${checkbox({ id: "nfSearch", label: "Include search suggestion", checked: false })}${field({ id: "nfSearchUrl", label: "Search page URL", value: "/search/" })}`,generate(root) {const siteName = root.querySelector("#nfSiteName").value;const siteUrl = root.querySelector("#nfSiteUrl").value;const message = root.querySelector("#nfMessage").value;const includeNav = root.querySelector("#nfNav").checked;const includeSearch = root.querySelector("#nfSearch").checked;const searchUrl = root.querySelector("#nfSearchUrl").value;let output = '<!DOCTYPE html>\n<html lang="en">\n<head>\n <meta charset="UTF-8">\n <meta name="viewport" content="width=device-width, initial-scale=1">\n' +' <title>404 - ' + htmlEscape(siteName || "Page Not Found") + '</title>\n' +' <style>\n * { margin: 0; padding: 0; box-sizing: border-box; }\n' +' body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #fff; color: #333; line-height: 1.6; }\n' +' .container { max-width: 600px; margin: 4rem auto; padding: 2rem; text-align: center; }\n' +' h1 { font-size: 4rem; color: #dc2626; margin-bottom: 0.5rem; }\n' +' h2 { font-size: 1.5rem; margin-bottom: 1rem; color: #1f2937; }\n' +' p { margin-bottom: 1rem; }\n' +' a { color: #2563eb; text-decoration: underline; }\n' +' nav { margin-bottom: 2rem; padding: 1rem; background: #f3f4f6; border-radius: 8px; }\n' +' nav a { margin: 0 0.75rem; }\n' +' .search-form { margin-top: 2rem; }\n' +' .search-form input[type="text"] { padding: 0.5rem; border: 1px solid #d1d5db; border-radius: 4px; width: 60%; }\n' +' .search-form button { padding: 0.5rem 1rem; background: #2563eb; color: #fff; border: none; border-radius: 4px; cursor: pointer; }\n' +' .home-link { display: inline-block; margin-top: 1.5rem; padding: 0.75rem 1.5rem; background: #2563eb; color: #fff !important; text-decoration: none; border-radius: 6px; }\n' +' </style>\n</head>\n<body>\n <div class="container">\n';if (includeNav) {output += ' <nav>\n' +' <a href="' + attrEscape(siteUrl) + '">Home</a>\n' +' <a href="' + attrEscape(siteUrl) + '/tools/">Tools</a>\n' +' <a href="' + attrEscape(siteUrl) + '/about/">About</a>\n' +' <a href="' + attrEscape(siteUrl) + '/contact/">Contact</a>\n' +' </nav>\n';}output += ' <h1>404</h1>\n <h2>Page Not Found</h2>\n' +(message ? ' <p>' + htmlEscape(message) + '</p>\n' : "") +' <p>The page you were looking for does not exist at <strong>' + htmlEscape(siteName) + '</strong>.</p>\n' +' <a href="' + attrEscape(siteUrl) + '" class="home-link">Go to Homepage</a>\n';if (includeSearch && searchUrl) {output += ' <div class="search-form">\n' +' <p>Try searching:</p>\n' +' <form action="' + attrEscape(searchUrl) + '" method="get">\n' +' <input type="text" name="q" placeholder="Search...">\n' +' <button type="submit">Search</button>\n' +' </form>\n </div>\n';}output += ' </div>\n</body>\n</html>';return { output };}};